stand.css:
.kl-h1{font-size:1.95em!important}
.zeichner{display:flex;align-items:center;justify-content:space-between}
.zeichner .rechts{text-align:right}
.blatt.fl.sk-1{--unten:16mm}
.legende{display:grid;grid-template-columns:1fr 1fr;gap:8mm;padding-top:5mm;border-top:.22mm solid rgba(138,117,69,.55)}
.leg{display:flex;gap:3.2mm;align-items:flex-start;font-size:.9em}.leg .spr p{margin:0}.leg .de{font-family:var(--serif);color:var(--navy)}.leg .bl{height:2em;flex:none;margin-top:.1em}
.g-z.reihe{margin-top:.34em}.g-z.reihe .z-t{display:flex;flex-wrap:wrap;gap:0 .5em}.g-z.reihe .z-t span{display:inline}
.g-z.reihe .z-t span::before{content:"/";margin-right:.5em;color:var(--messing)}
.g-z.kopf{margin-top:.9em}
.g-z.inhalt{margin-top:.7em;padding-right:calc(var(--preis) + 6mm)}.g-z.inhalt .z-t span{margin-top:.4em}
.g.breit .g-d,.g.breit .g-l{padding-right:0}
.hin.g{padding-bottom:1em}
.beilagen{display:flex;justify-content:center;padding-top:.9em}
.fl ul.sorten{margin-top:.4em}
.drei{display:grid;grid-template-columns:repeat(3,1fr);gap:7mm;border-top:.3mm solid var(--messing);padding-top:6mm}
.drei h2{font-size:1.5em;margin:0 0 .4em}.drei p{font-size:.9em}
.eng p{margin:0 0 .1em!important;font-size:.9em}
.gruss p{margin:0 0 .7em}
.weine .wn{display:grid;grid-template-columns:17mm 1fr;column-gap:3mm}
.wn-h b{display:block}.wn-h{padding-top:.2em}
.weine .g-l{padding-right:calc(var(--preis) + 16mm)}
.weine .g-k2{margin-top:.1em}
.blatt.fl.sk-13{--unten:30mm}
.sk-13 .fl-fuss{text-align:left}
